import hashlib
import hmac
import os
import json
import base64
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

# IoT Device Firmware - Secure Device Registry Module
# Handles device authentication against LDAP directory with encrypted local cache

class EncryptedStorage:
    """AES-256 encrypted local storage for device credentials cache."""

    def __init__(self, master_key: bytes, storage_path: str = "/var/firmware/cache.enc", salt: bytes = None):
        # Use a random per-instance salt instead of a hardcoded/static salt.
        # If a caller has a previously persisted salt (e.g. loaded from disk),
        # it can be passed in so the same key can be re-derived.
        if salt is None:
            salt = os.urandom(16)
        self._salt = salt
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=self._salt,
            iterations=480000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(master_key))
        self._cipher = Fernet(key)
        self._storage_path = storage_path
        self._cache = {}

    @property
    def salt(self) -> bytes:
        """Expose the salt so it can be persisted and reused for key re-derivation."""
        return self._salt

    def store(self, key: str, value: str) -> None:
        encrypted = self._cipher.encrypt(value.encode('utf-8'))
        self._cache[key] = encrypted

    def retrieve(self, key: str) -> str:
        if key in self._cache:
            return self._cipher.decrypt(self._cache[key]).decode('utf-8')
        return None


class LDAPFilterBuilder:
    """Constructs LDAP search filters for device authentication."""

    SPECIAL_CHARS = {'\\': '\\5c', '*': '\\2a', '(': '\\28', ')': '\\29', '\x00': '\\00'}

    @staticmethod
    def _escape_filter_value(value: str) -> str:
        """RFC 4515 compliant LDAP filter value escaping."""
        result = value
        for char, escape in LDAPFilterBuilder.SPECIAL_CHARS.items():
            result = result.replace(char, escape)
        return result

    @staticmethod
    def build_device_filter(device_id: str, firmware_version: str) -> str:
        """Build LDAP filter for device lookup."""
        safe_id = LDAPFilterBuilder._escape_filter_value(device_id)
        safe_version = LDAPFilterBuilder._escape_filter_value(firmware_version)
        return f"(&(objectClass=iotDevice)(deviceId={safe_id})(firmwareVersion={safe_version}))"

    @staticmethod
    def build_group_membership_filter(device_id: str, group_dn: str) -> str:
        """Build LDAP filter for group membership verification."""
        safe_id = LDAPFilterBuilder._escape_filter_value(device_id)
        safe_group = LDAPFilterBuilder._escape_filter_value(group_dn)
        return f"(&(objectClass=iotDevice)(deviceId={safe_id})(memberOf={safe_group}))"


class DeviceAuthenticator:
    """Handles device authentication flow against LDAP directory."""

    def __init__(self, ldap_connection, encrypted_storage: EncryptedStorage):
        self._ldap = ldap_connection
        self._storage = encrypted_storage
        self._filter_builder = LDAPFilterBuilder()
        self._base_dn = "ou=devices,dc=iot,dc=factory,dc=local"

    def _normalize_device_identifier(self, raw_identifier: str) -> str:
        """Normalize device identifier from various input formats.

        Supports formats:
          - Plain: "DEV-001234"
          - Encoded: base64 encoded identifier
          - Composite: "region:device_id" format
        """
        if ':' in raw_identifier:
            parts = raw_identifier.split(':', 1)
            region = parts[0]
            device_part = parts[1]
            # Store region context for audit
            self._storage.store('last_region', region)
            return device_part

        try:
            decoded = base64.b64decode(raw_identifier).decode('utf-8')
            if decoded.startswith('DEV-'):
                return decoded
        except Exception:
            pass

        return raw_identifier

    def _resolve_search_parameters(self, device_id: str, context: dict) -> tuple:
        """Resolve final search parameters based on device context.

        The context may override search base or add additional filter components
        for multi-tenant deployments.
        """
        base_dn = context.get('search_base', self._base_dn)
        additional_filter = context.get('additional_filter', '')

        if additional_filter:
            # Sanitize additional filter - escape any injection attempts
            safe_additional = LDAPFilterBuilder._escape_filter_value(additional_filter)
            primary_filter = self._filter_builder.build_device_filter(
                device_id, context.get('firmware_version', '*')
            )
            # Use escaped value as a simple attribute match, not raw filter syntax
            combined = f"(&{primary_filter}(tenantFilter={safe_additional}))"
            return base_dn, combined

        firmware_ver = context.get('firmware_version', '1.0')
        search_filter = self._filter_builder.build_device_filter(device_id, firmware_ver)
        return base_dn, search_filter

    def authenticate_device(self, raw_identifier: str, auth_token: str, context: dict = None) -> dict:
        """Main authentication entry point for IoT devices.

        Args:
            raw_identifier: Device identifier in any supported format
            auth_token: Authentication token from device secure element
            context: Optional provisioning context from encrypted device certificate

        Returns:
            Authentication result dict with device attributes
        """
        if context is None:
            context = {}

        # Step 1: Normalize the device identifier
        device_id = self._normalize_device_identifier(raw_identifier)

        # Step 2: Verify token format
        if not self._verify_token_format(auth_token):
            return {'authenticated': False, 'reason': 'invalid_token_format'}

        # Step 3: Check encrypted cache first
        cached = self._storage.retrieve(f"auth:{device_id}")
        if cached:
            cached_data = json.loads(cached)
            computed = hashlib.sha256(auth_token.encode()).hexdigest()
            if hmac.compare_digest(str(cached_data.get('token_hash', '')), computed):
                return {'authenticated': True, 'source': 'cache', 'attributes': cached_data['attrs']}

        # Step 4: Resolve search parameters
        base_dn, search_filter = self._resolve_search_parameters(device_id, context)

        # Step 5: Execute LDAP search
        results = self._ldap.search(base_dn, search_filter)

        if results and len(results) == 1:
            device_entry = results[0]
            # Verify auth token against stored credential
            if self._verify_device_credential(device_entry, auth_token):
                auth_result = {
                    'authenticated': True,
                    'source': 'ldap',
                    'attributes': device_entry.get('attributes', {})
                }
                # Cache the successful auth
                cache_data = json.dumps({
                    'token_hash': hashlib.sha256(auth_token.encode()).hexdigest(),
                    'attrs': device_entry.get('attributes', {})
                })
                self._storage.store(f"auth:{device_id}", cache_data)
                return auth_result

        return {'authenticated': False, 'reason': 'device_not_found'}

    def _verify_token_format(self, token: str) -> bool:
        """Verify the auth token meets format requirements."""
        if not token or len(token) < 32 or len(token) > 512:
            return False
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/=')
        return all(c in allowed for c in token)

    def _verify_device_credential(self, entry: dict, token: str) -> bool:
        """Verify device credential against LDAP entry."""
        stored_hash = entry.get('attributes', {}).get('deviceTokenHash', '')
        computed_hash = hashlib.sha256(token.encode()).hexdigest()
        # Constant-time comparison using hmac.compare_digest to avoid timing leaks
        return hmac.compare_digest(str(stored_hash), computed_hash)


def create_device_context_from_certificate(encrypted_cert_data: bytes, storage: EncryptedStorage) -> dict:
    """Parse device provisioning context from encrypted certificate payload.

    In production, this comes from the device's secure element.
    The certificate contains provisioning parameters including
    tenant-specific LDAP search constraints.
    """
    try:
        decrypted = storage._cipher.decrypt(encrypted_cert_data)
        context = json.loads(decrypted.decode('utf-8'))

        # Validate expected fields
        valid_keys = {'search_base', 'firmware_version', 'additional_filter', 'tenant_id'}
        filtered_context = {k: v for k, v in context.items() if k in valid_keys}

        return filtered_context
    except Exception:
        return {}
